-- Dashboard user invitations (Team & Users → Invite) send the "user_invitation" event.
-- The MJG fork mapped it to its "6-Week Challenge Invitation"; point it at a SIG template.
-- Generated by scripts/build-email-templates.mjs. The old template row is left in place, unused.

insert into public.email_templates (name, slug, subject, preheader, html_body, text_body, category, status, available_fields)
values (
  'SIG Dashboard Invitation',
  'sig-dashboard-invitation',
  $tpl$You’re invited to the Strategic Income Group dashboard$tpl$,
  'Accept your invitation and choose a password.',
  $tpl$<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="color-scheme" content="light" />
  <meta name="supported-color-schemes" content="light" />
  <title>You’re invited to the Strategic Income Group dashboard</title>
  <link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;600&display=swap" rel="stylesheet" />
</head>
<body style="margin:0;padding:0;background:#f8f5ef;-webkit-text-size-adjust:100%;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;">Accept your invitation and choose a password.&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f8f5ef" style="background:#f8f5ef;">
    <tr>
      <td align="center" style="padding:32px 16px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;">
          <!-- Header -->
          <tr>
            <td bgcolor="#0d2568" style="background:#0d2568;border-radius:12px 12px 0 0;padding:26px 32px;">
              <img src="https://app.strategicincomegroup.com/brand/sig-logo-white.png" width="200" alt="Strategic Income Group" style="display:block;width:200px;max-width:100%;height:auto;border:0;" />
            </td>
          </tr>
          <tr><td height="3" bgcolor="#c9a46e" style="background:#c9a46e;font-size:0;line-height:0;">&nbsp;</td></tr>
          <!-- Card -->
          <tr>
            <td bgcolor="#ffffff" style="background:#ffffff;border:1px solid #e7e1d6;border-top:0;border-radius:0 0 12px 12px;padding:36px 32px 32px;">
              <p style="margin:0 0 10px;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:12px;font-weight:600;letter-spacing:0.18em;text-transform:uppercase;color:#8f6a29;">You’re invited</p>
              <h1 style="margin:0 0 16px;font-family:'DM Serif Display', Georgia, 'Times New Roman', serif;font-size:30px;font-weight:400;line-height:1.15;color:#141c33;">Join the Strategic Income Group dashboard</h1>
              <p style="margin:0 0 14px;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:15px;line-height:1.65;color:#141c33;">You’ve been invited to the Strategic Income Group dashboard — clients, bookings and events, communications, content and projects, behind secure sign-in.</p><p style="margin:0 0 14px;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:15px;line-height:1.65;color:#141c33;">Accept the invitation to choose your password and sign in.</p>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:28px 0 8px;">
  <tr>
    <td bgcolor="#0d2568" style="border-radius:6px;">
      <a href="{{invite_url}}" target="_blank" style="display:inline-block;padding:13px 26px;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:15px;font-weight:600;line-height:1;color:#ffffff;text-decoration:none;border-radius:6px;">Accept invitation &rarr;</a>
    </td>
  </tr>
</table><p style="margin:12px 0 0;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:13px;line-height:1.6;color:#5d6577;">This invitation is for <strong>{{email}}</strong>.</p>
<p style="margin:20px 0 0;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:12px;line-height:1.6;color:#5d6577;">
  Button not working? Copy this link into your browser:<br />
  <a href="{{invite_url}}" style="color:#0d2568;word-break:break-all;">{{invite_url}}</a>
</p>
              <hr style="border:0;border-top:1px solid #e7e1d6;margin:32px 0 20px;" />
              <p style="margin:0;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:12px;line-height:1.6;color:#5d6577;">
                If you didn’t request this email, you can safely ignore it. Questions? Call us at
                <a href="tel:+14804667070" style="color:#0d2568;text-decoration:none;">(480) 466-7070</a>.
              </p>
            </td>
          </tr>
          <!-- Footer -->
          <tr>
            <td align="center" style="padding:24px 16px 8px;font-family:Inter, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;font-size:12px;line-height:1.7;color:#5d6577;">
              <span style="font-family:'DM Serif Display', Georgia, 'Times New Roman', serif;font-size:14px;color:#141c33;">Strategize. Invest. <em style="color:#8f6a29;">Give.</em></span><br />
              Strategic Income Group · 2330 W Ray Rd. #3, Chandler, AZ 85224<br />
              20542 N. Lake Pleasant Rd. #119, Peoria, AZ 85382<br />
              <a href="{{site_url}}" style="color:#5d6577;">app.strategicincomegroup.com</a>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
$tpl$,
  $tpl$You’ve been invited to the Strategic Income Group dashboard.

Accept your invitation and choose a password: {{invite_url}}

Questions? Call (480) 466-7070.$tpl$,
  'general',
  'active',
  array['invite_url', 'email', 'site_url']
)
on conflict (slug) do update
  set subject = excluded.subject, html_body = excluded.html_body, text_body = excluded.text_body,
      status = 'active', updated_at = now();

update public.email_template_mappings
   set template_id = (select id from public.email_templates where slug = 'sig-dashboard-invitation'),
       enabled = true,
       updated_at = now()
 where event_key = 'user_invitation';
